-- Optional non-secret linkage follows the account through backups and cloud sync.
-- No provider credentials, session IDs or full IBANs are stored here.
ALTER TABLE public.finance_accounts ADD COLUMN IF NOT EXISTS bank_identity_key text
    CHECK (bank_identity_key IS NULL OR bank_identity_key ~ '^enable:[a-f0-9]{64}$');
CREATE UNIQUE INDEX IF NOT EXISTS finance_accounts_bank_identity ON public.finance_accounts(owner_id, workspace_id, bank_identity_key)
    WHERE deleted_at IS NULL AND bank_identity_key IS NOT NULL;
ALTER TABLE public.finance_transactions ADD COLUMN IF NOT EXISTS bank_entry_key text;
CREATE UNIQUE INDEX IF NOT EXISTS finance_transactions_bank_entry ON public.finance_transactions(owner_id, workspace_id, bank_entry_key)
    WHERE deleted_at IS NULL AND bank_entry_key IS NOT NULL;
CREATE OR REPLACE FUNCTION finance_private.backup_contract() RETURNS jsonb LANGUAGE sql IMMUTABLE
SET search_path = '' AS $contract$ SELECT '[{"key": "institutions", "table": "finance_institutions", "fields": {"id": "id", "name": "name", "colorHex": "color_hex", "notes": "notes", "createdAt": "created_at", "updatedAt": "updated_at"}, "dates": ["createdAt", "updatedAt"], "months": []}, {"key": "accounts", "table": "finance_accounts", "fields": {"id": "id", "name": "name", "typeRaw": "type", "currencyCode": "currency_code", "openingBalanceMinor": "opening_balance_minor", "openingDate": "opening_date", "annualInterestRate": "annual_interest_rate", "targetBalanceMinor": "target_balance_minor", "creditLimitMinor": "credit_limit_minor", "includeInNetWorth": "include_in_net_worth", "isArchived": "is_archived", "sortOrder": "sort_order", "notes": "notes", "lastUpdatedAt": "last_updated_at", "createdAt": "created_at", "updatedAt": "updated_at", "institutionID": "institution_id", "bankIdentityKey": "bank_identity_key"}, "dates": ["openingDate", "lastUpdatedAt", "createdAt", "updatedAt"], "months": []}, {"key": "categories", "table": "finance_categories", "fields": {"id": "id", "name": "name", "kindRaw": "kind", "systemImage": "system_image", "colorHex": "color_hex", "isArchived": "is_archived", "isSystem": "is_system", "sortOrder": "sort_order", "createdAt": "created_at", "updatedAt": "updated_at"}, "dates": ["createdAt", "updatedAt"], "months": []}, {"key": "cards", "table": "finance_cards", "fields": {"id": "id", "name": "name", "typeRaw": "type", "lastFour": "last_four", "limitMinor": "limit_minor", "limitKindRaw": "limit_kind", "onlinePurchasesEnabled": "online_purchases_enabled", "contactlessEnabled": "contactless_enabled", "atmWithdrawalsEnabled": "atm_withdrawals_enabled", "internationalPaymentsEnabled": "international_payments_enabled", "cashbackEnabled": "cashback_enabled", "cashbackPercent": "cashback_percent", "roundUpEnabled": "round_up_enabled", "isArchived": "is_archived", "notes": "notes", "createdAt": "created_at", "updatedAt": "updated_at", "institutionID": "institution_id", "linkedAccountID": "linked_account_id"}, "dates": ["createdAt", "updatedAt"], "months": []}, {"key": "reservedFunds", "table": "finance_reserved_funds", "fields": {"id": "id", "name": "name", "amountMinor": "amount_minor", "notes": "notes", "createdAt": "created_at", "updatedAt": "updated_at", "accountID": "account_id"}, "dates": ["createdAt", "updatedAt"], "months": []}, {"key": "categoryRules", "table": "finance_category_rules", "fields": {"id": "id", "phrase": "phrase", "transactionTypeRaw": "transaction_type", "isActive": "is_active", "createdAt": "created_at", "updatedAt": "updated_at", "categoryID": "category_id"}, "dates": ["createdAt", "updatedAt"], "months": []}, {"key": "recurringBudgets", "table": "finance_recurring_budgets", "fields": {"id": "id", "startMonth": "start_month", "endMonth": "end_month", "baseLimitMinor": "base_limit_minor", "remainderChoiceRaw": "remainder_choice", "createdAt": "created_at", "updatedAt": "updated_at", "categoryID": "category_id"}, "dates": ["startMonth", "endMonth", "createdAt", "updatedAt"], "months": ["startMonth", "endMonth"]}, {"key": "budgets", "table": "finance_monthly_budgets", "fields": {"id": "id", "monthStart": "month_start", "limitMinor": "limit_minor", "notes": "notes", "createdAt": "created_at", "updatedAt": "updated_at", "categoryID": "category_id"}, "dates": ["monthStart", "createdAt", "updatedAt"], "months": ["monthStart"]}, {"key": "goals", "table": "finance_savings_goals", "fields": {"id": "id", "name": "name", "targetAmountMinor": "target_amount_minor", "currentAmountMinor": "current_amount_minor", "targetDate": "target_date", "colorHex": "color_hex", "notes": "notes", "isCompleted": "is_completed", "createdAt": "created_at", "updatedAt": "updated_at", "linkedAccountID": "linked_account_id"}, "dates": ["targetDate", "createdAt", "updatedAt"], "months": []}, {"key": "recurringMovements", "table": "finance_recurring_movements", "fields": {"id": "id", "name": "name", "typeRaw": "type", "amountMinor": "amount_minor", "descriptionText": "description_text", "notes": "notes", "frequencyRaw": "frequency", "interval": "interval", "nextDueDate": "next_due_date", "endDate": "end_date", "isActive": "is_active", "isSubscription": "is_subscription", "postsAutomatically": "posts_automatically", "createdAt": "created_at", "updatedAt": "updated_at", "sourceAccountID": "source_account_id", "destinationAccountID": "destination_account_id", "categoryID": "category_id"}, "dates": ["nextDueDate", "endDate", "createdAt", "updatedAt"], "months": []}, {"key": "importBatches", "table": "finance_import_batches", "fields": {"id": "id", "fileName": "file_name", "sourceRaw": "source", "institutionName": "institution_name", "importedAt": "imported_at", "importedRows": "imported_rows", "skippedDuplicates": "skipped_duplicates", "possibleDuplicates": "possible_duplicates", "checksum": "checksum", "notes": "notes"}, "dates": ["importedAt"], "months": []}, {"key": "snapshots", "table": "finance_balance_snapshots", "fields": {"id": "id", "date": "date", "balanceMinor": "balance_minor", "sourceRaw": "source", "notes": "notes", "createdAt": "created_at", "accountID": "account_id"}, "dates": ["date", "createdAt"], "months": []}, {"key": "transactions", "table": "finance_transactions", "fields": {"id": "id", "date": "date", "typeRaw": "type", "amountMinor": "amount_minor", "descriptionText": "description_text", "notes": "notes", "isReconciled": "is_reconciled", "fingerprint": "fingerprint", "duplicateStateRaw": "duplicate_state", "externalID": "external_id", "importBatchID": "import_batch_id", "recurringMovementID": "recurring_movement_id", "reservedFundID": "reserved_fund_id", "reservedAmountMinor": "reserved_amount_minor", "createdAt": "created_at", "updatedAt": "updated_at", "sourceAccountID": "source_account_id", "destinationAccountID": "destination_account_id", "categoryID": "category_id", "bankEntryKey": "bank_entry_key"}, "dates": ["date", "createdAt", "updatedAt"], "months": []}]'::jsonb $contract$;
